-- ============================================================

insert into wooz_trip_kid_tags (id, label, filterable, sort_order) values
  ('baby_chair', '아기의자', true, 1),
  ('kids_menu', '유아 메뉴', true, 2),
  ('parking', '주차', true, 3),
  ('stroller', '유모차', true, 4),
